const std = @import("std"); const fla2 = std.compress.flate;
pub fn zlibOfzz(allo: std.mem.Allocator, body: []const u8) ![]u8 { var outw = try std.Io.Writer.Allocating.initCapacity(allo, 1024); defer outw.deinit(); const wind = try allo.alloc(u8, fla2.max_window_len); defer allo.free(wind); var comp = try fla2.Compress.init(&outw.writer, wind, .zlib, .default); try comp.writer.writeAll(body); try comp.finish(); return outw.toOwnedSlice(); }
pub const Optz = struct { fla2: bool = false, cmap: bool = false, objs: bool = false, root: bool = true, enc2: bool = false, nofo: bool = false };
fn strm(allo: std.mem.Allocator, buf4: *std.ArrayList(u8), num2: u32, ext2: []const u8, body: []const u8, flat: bool) !void { const data = if (flat) try zlibOfzz(allo, body) else try allo.dupe(u8, body); defer allo.free(data); try buf4.print(allo, "{d} 0 obj\n<< /Length {d} {s}{s} >>\nstream\n", .{ num2, data.len, if (flat) "/Filter /FlateDecode " else "", ext2 }); try buf4.appendSlice(allo, data); try buf4.appendSlice(allo, "\nendstream\nendobj\n"); }
const CMAP = "/CIDInit /ProcSet findresource begin begincmap 1 begincodespacerange <0000> <FFFF> endcodespacerange 2 beginbfchar <0001> <0048> <0002> <0069> endbfchar 1 beginbfrange <0003> <0005> <0041> endbfrange endcmap end";
pub fn build(allo: std.mem.Allocator, pag2: []const []const u8, optz: Optz) ![]u8 { var buf4: std.ArrayList(u8) = .empty; errdefer buf4.deinit(allo); try buf4.appendSlice(allo, "%PDF-1.5\n"); const fnum: u32 = 5; const cnum: u32 = 6; const first: u32 = 10; var kids: std.ArrayList(u8) = .empty; defer kids.deinit(allo); for (pag2, 0..) |_, ind2| try kids.print(allo, "{d} 0 R ", .{first + @as(u32, @intCast(ind2)) * 2});
const catd = "<< /Type /Catalog /Pages 2 0 R >>"; const pgsd = try std.fmt.allocPrint(allo, "<< /Type /Pages /Kids [{s}] /Count {d} >>", .{ kids.items, pag2.len }); defer allo.free(pgsd);
if (optz.objs) { var inne: std.ArrayList(u8) = .empty; defer inne.deinit(allo); var head: std.ArrayList(u8) = .empty; defer head.deinit(allo); try head.print(allo, "1 0 2 {d} ", .{catd.len + 1}); try inne.print(allo, "{s} {s}", .{ catd, pgsd }); const ext2 = try std.fmt.allocPrint(allo, "/Type /ObjStm /N 2 /First {d} ", .{head.items.len}); defer allo.free(ext2); const whol = try std.fmt.allocPrint(allo, "{s}{s}", .{ head.items, inne.items }); defer allo.free(whol); try strm(allo, &buf4, 9, ext2, whol, true); } else { try buf4.print(allo, "1 0 obj\n{s}\nendobj\n2 0 obj\n{s}\nendobj\n", .{ catd, pgsd }); }
if (!optz.nofo) { if (optz.cmap) { try buf4.print(allo, "{d} 0 obj\n<< /Type /Font /Subtype /Type0 /BaseFont /X /ToUnicode {d} 0 R >>\nendobj\n", .{ fnum, cnum }); try strm(allo, &buf4, cnum, "", CMAP, optz.fla2); } else try buf4.print(allo, "{d} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n", .{fnum}); }
for (pag2, 0..) |con5, ind2| { const pnzz = first + @as(u32, @intCast(ind2)) * 2; try buf4.print(allo, "{d} 0 obj\n<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 {d} 0 R >> >> /Contents {d} 0 R >>\nendobj\n", .{ pnzz, fnum, pnzz + 1 }); try strm(allo, &buf4, pnzz + 1, "", con5, optz.fla2); }
try buf4.print(allo, "trailer\n<< {s}/Size 40 {s}>>\n%%EOF\n", .{ if (optz.root) "/Root 1 0 R " else "", if (optz.enc2) "/Encrypt 99 0 R " else "" }); return buf4.toOwnedSlice(allo); }
